const body = $input.first().json.body || $input.first().json;
const userId = body.userId || body.user_id || 'test-user-123';
const requestText = body.requestText || body.request || '';
const budget = body.budget ?? null;
const suggestions = body.suggestions || [];
const picks = body.picks || [];

const selections = [];
const reasoning = [];

for (const pick of picks) {
  const quantity = pick.quantity || 1;
  const catSuggestion = suggestions.find(s => s.category === pick.category);
  if (!catSuggestion) {
    selections.push({ category: pick.category, item: null, quantity, skippedReason: 'category not found in original suggestions' });
    continue;
  }
  const chosen = (catSuggestion.options || []).find(o => o.productId === pick.productId);
  if (!chosen) {
    selections.push({ category: pick.category, item: null, quantity, skippedReason: 'chosen productId not found among shown options' });
    continue;
  }
  selections.push({ category: pick.category, item: chosen, quantity, skippedReason: null });
  reasoning.push(`User picked "${chosen.description}" x${quantity} for ${pick.category}.`);
}

const total = selections.reduce((sum, s) => sum + (s.item ? s.item.price * s.quantity : 0), 0);
const freeDeliveryMinimum = 35;

return [{ json: {
  selections,
  total: Number(total.toFixed(2)),
  budget,
  freeDeliveryMinimum,
  metFreeDeliveryMinimum: total >= freeDeliveryMinimum,
  reasoning,
  userId,
  requestText,
  suggestionsShown: suggestions
} }];

const raw = $json.data ?? $json;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
if (!text || !text.trim()) {
  throw new Error('Cart Agent returned an empty response — check its own execution log.');
}
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1 || end < start) {
  throw new Error('Cart Agent did not return any JSON object. Raw text: ' + text.slice(0, 800));
}
const cleaned = text.slice(start, end + 1);
try {
  return [{ json: JSON.parse(cleaned) }];
} catch (e) {
  throw new Error('Cart Agent returned malformed JSON: ' + e.message + ' | extracted: ' + cleaned.slice(0, 800));
}
